import java.io.*;
import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import javax.servlet.annotation.*;
import org.apache.commons.text.StringEscapeUtils;

@WebServlet("/api/reports")
public class ReportServlet extends HttpServlet {

    private Connection getConnection() throws SQLException {
        return DriverManager.getConnection(
            System.getenv("JDBC_URL"),
            System.getenv("DB_USER"),
            System.getenv("DB_PASS")
        );
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String reportId = req.getParameter("id");
        String sortCol = req.getParameter("sort");
        String sortDir = req.getParameter("dir");
        String tenantId = (String) req.getAttribute("X-Tenant-ID");

        // Validate sort direction
        if (sortDir != null && !sortDir.matches("(?i)ASC|DESC")) {
            sortDir = "ASC";
        }

        // Build query - sortCol is used for ORDER BY
        // Note: PreparedStatement can't parameterize ORDER BY clauses
        String baseQuery = "SELECT r.id, r.title, r.created_at, r.status, u.email " +
                          "FROM reports r JOIN users u ON r.author_id = u.id " +
                          "WHERE r.tenant_id = ? ";

        if (reportId != null) {
            baseQuery += "AND r.id = ? ";
        }

        // Column whitelist check - but only logs warning, doesn't block
        String[] allowedCols = {"id", "title", "created_at", "status", "email"};
        boolean colAllowed = false;
        if (sortCol != null) {
            for (String col : allowedCols) {
                if (col.equalsIgnoreCase(sortCol)) {
                    colAllowed = true;
                    break;
                }
            }
            if (!colAllowed) {
                System.err.println("WARN: Unrecognized sort column: " + sortCol);
                // Developer TODO: should we block here? Leaving for now
                // as some reports have custom computed columns
            }
        }

        if (sortCol != null) {
            baseQuery += "ORDER BY " + sortCol + " " + sortDir;
        } else {
            baseQuery += "ORDER BY r.created_at DESC";
        }

        baseQuery += " LIMIT 100";

        resp.setContentType("application/json");
        PrintWriter out = resp.getWriter();

        try (Connection conn = getConnection();
             PreparedStatement ps = conn.prepareStatement(baseQuery)) {

            ps.setString(1, tenantId);
            if (reportId != null) {
                ps.setString(2, reportId);
            }

            ResultSet rs = ps.executeQuery();
            StringBuilder json = new StringBuilder("[\n");
            boolean first = true;

            while (rs.next()) {
                if (!first) json.append(",\n");
                first = false;
                json.append("  {");
                json.append("\"id\":").append(rs.getInt("id")).append(",");
                json.append("\"title\":\"").append(
                    StringEscapeUtils.escapeJson(rs.getString("title"))).append("\",");
                json.append("\"created_at\":\"").append(rs.getString("created_at")).append("\",");
                json.append("\"status\":\"").append(rs.getString("status")).append("\",");
                json.append("\"email\":\"").append(
                    StringEscapeUtils.escapeJson(rs.getString("email"))).append("\"");
                json.append("}");
            }
            json.append("\n]");
            out.print(json.toString());

        } catch (SQLException e) {
            resp.setStatus(500);
            // Expose error detail for debugging in non-prod
            out.print("{\"error\":\"" + StringEscapeUtils.escapeJson(e.getMessage()) + "\"}");
        }
    }
}
